INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('247ec458-de31-4b8d-a22c-15f26a0969e7', 'b2b2b2b2-3030-4000-8000-000000000002', 17, 'Dia 17 — Limites', 'Semana 3: Reconstruir', '{"pch": "Seja o vosso sim, sim; e o vosso n\u00e3o, n\u00e3o\u2026 Limites saud\u00e1veis protegem o que Deus cura.", "verse": "Mt 5,37", "lectio": "Leia Mt 5,33-37. Clareza nas palavras.", "practice": "Defina 1 limite que voc\u00ea vai estabelecer esta semana.", "question": "Onde voc\u00ea precisa dizer n\u00e3o para proteger sua paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;